export const SIMPACK_STD_LIB_WASM_BASE64 =
  "";

let cachedWasmBytes: Uint8Array | undefined;

/**
 * Decodes the pre-bundled `@modelscript/simpack-std-lib` `runtime.wasm` binary in Node.js, Browsers, or Web Workers.
 */
export function getSimpackStdLibWasmBytes(): Uint8Array {
  if (!cachedWasmBytes) {
    cachedWasmBytes = decodeBase64Wasm(SIMPACK_STD_LIB_WASM_BASE64);
  }
  return cachedWasmBytes;
}
